algorithms.pseudocode:
Algorithm CongruenceClosure(T, E):
  UF <- new UnionFind
  for t in T: UF.make_set(t)
  for (l, r) in E: UF.union(l, r)
  repeat:
    changed <- false
    for f(a1, a2), f(b1, b2) in T:
      if UF.find(a1) = UF.find(b1) and UF.find(a2) = UF.find(b2):
        if UF.find(f(a1,a2)) != UF.find(f(b1,b2)):
          UF.union(f(a1,a2), f(b1,b2))
          changed <- true
  until not changed
  return UF

Complexity: O(n^3 * alpha(n))

Algorithm ExtractMinCost(UF, cost):
  best <- {}
  for t in T:
    root <- UF.find(t)
    if root not in best or cost(t) < cost(best[root]):
      best[root] <- t
  return best

Complexity: O(n * alpha(n))
